$$
A=\begin{bmatrix}1 & 0 \\ 0 & -11\end{bmatrix}
$$

$$
B=\begin{bmatrix}-7 & 0 & 0 & 0 \\ 0 & 3 & 0 & 0 \\ 0 & 0 & 8 & 0 \\ 0 & 0 & 0 & 1\end{bmatrix}
$$

$$
C=\begin{bmatrix}-7 & 0 & -2 \\ 0 & -10 & -2 \\ 0 & -4 & 7\end{bmatrix}
$$

