$$
A=\begin{bmatrix}-9 & 0 \\ 5 & 7\end{bmatrix}
$$

$$
B=\begin{bmatrix}-10 & 9 & 0 & 0 \\ 0 & 9 & 0 & 0 \\ 0 & 0 & -10 & 0 \\ 0 & 0 & 0 & -8\end{bmatrix}
$$

$$
